declare @z_ds_cd_dong_goi nvarchar(4000), @z_ds_kho_thanh_pham nvarchar(4000)
select @z_ds_cd_dong_goi = ltrim(rtrim(val)) from options where name = 'z_ds_cd_dong_goi'
select @z_ds_kho_thanh_pham = ltrim(rtrim(val)) from options where name = 'z_ds_kho_thanh_pham'
select @z_ds_cd_dong_goi = isnull(@z_ds_cd_dong_goi, ''), @z_ds_kho_thanh_pham = isnull(@z_ds_kho_thanh_pham, '')
select 'this._cd_dong_goi = '''+@z_ds_cd_dong_goi+''';this._kho_tp = '''+@z_ds_kho_thanh_pham+''';active$VoucherFilter$(this);' as message
return

			
		
		&XMLWhenFilterClosing;
		
		
			
				
select @den_ngay as den_ngay
exec zrpt_284 @den_ngay, @ma_kho, @ma_cd, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin, @kh_yn

			
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	var d= new Date();
	d.setDate(d.getDate() - 1);
	f.setItemValues('den_ngay, ma_kho, ma_cd', [d, f._kho_tp, f._cd_dong_goi]);
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItem('den_ngay').value, true]]];
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

		
	

	&OutlineCss;
